function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

var PRE=['酷','小','大','老','阿','甜','冷','醉','迷','星'];
var MID=['风','云','月','海','星','糖','橙','柠','可乐','猫','熊','鹿','鱼','茶','墨'];
var SUF=['酱','君','同学','宝宝','怪','侠','控','党','先生','小姐'];
var ENA=['Shadow','Neo','Luna','Echo','Pixel','Nova','Zen','Onyx'];
var ENB=['Wolf','Fox','Star','Moon','Storm','Flame','Ice','Wind'];
function gen(seed, style){
  var r=rngFactory(seed);
  if(style==='en'){ return ENA[Math.floor(r()*ENA.length)]+ENB[Math.floor(r()*ENB.length)]; }
  return PRE[Math.floor(r()*PRE.length)]+MID[Math.floor(r()*MID.length)]+SUF[Math.floor(r()*SUF.length)];
}
var EXPORTS={gen:gen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NicknameForgePure = EXPORTS; }
